import{_ as i,o as t,c as a,aA as n}from"./chunks/framework.Dl8a02nG.js";const g=JSON.parse('{"title":"Automated Batch Pipelines","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/batch-processing.md","filePath":"tutorials/batch-processing.md","lastUpdated":null}'),s={name:"tutorials/batch-processing.md"};function o(r,e,l,p,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="Automated-Batch-Pipelines" tabindex="-1">Automated Batch Pipelines <a class="header-anchor" href="#Automated-Batch-Pipelines" aria-label="Permalink to &quot;Automated Batch Pipelines {#Automated-Batch-Pipelines}&quot;">​</a></h1><p>Analyzing an entire cohort is the ultimate goal of most EEG experiments. While you can write your own processing loops, <code>EegFun.jl</code> is built around a powerful automated pipeline system that handles the complexity of file discovery, error isolation, and cohort-wide reporting for you.</p><h2 id="1.-Single-Line-Execution" tabindex="-1">1. Single-Line Execution <a class="header-anchor" href="#1.-Single-Line-Execution" aria-label="Permalink to &quot;1. Single-Line Execution {#1.-Single-Line-Execution}&quot;">​</a></h2><p>The core of the system is the <code>preprocess_v1</code> function. By passing it a single TOML configuration file, you trigger a multi-stage transformation across all your participants.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the entire batch analysis</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">preprocess_v1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_study_config.toml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="2.-The-Internal-Lifecycle" tabindex="-1">2. The Internal Lifecycle <a class="header-anchor" href="#2.-The-Internal-Lifecycle" aria-label="Permalink to &quot;2. The Internal Lifecycle {#2.-The-Internal-Lifecycle}&quot;">​</a></h2><p>When you run an automated pipeline, it doesn&#39;t just &quot;apply a script&quot; to files. It manages a sophisticated lifecycle consisting of several high-level phases:</p><h3 id="Phase-1:-Environment-Setup" tabindex="-1">Phase 1: Environment Setup <a class="header-anchor" href="#Phase-1:-Environment-Setup" aria-label="Permalink to &quot;Phase 1: Environment Setup {#Phase-1:-Environment-Setup}&quot;">​</a></h3><p>The pipeline first loads your shared resources:</p><ul><li><p>Parses the <strong>TOML configuration</strong> and merges it with package defaults.</p></li><li><p>Loads the <strong>Electrode Layout</strong> and calculates spatial neighbors for artifact repair.</p></li><li><p>Discovers all <strong>Raw Data Files</strong> matching your selection patterns.</p></li></ul><h3 id="Phase-2:-Continuous-Level-Processing" tabindex="-1">Phase 2: Continuous-Level Processing <a class="header-anchor" href="#Phase-2:-Continuous-Level-Processing" aria-label="Permalink to &quot;Phase 2: Continuous-Level Processing {#Phase-2:-Continuous-Level-Processing}&quot;">​</a></h3><p>For each file, the pipeline performs initial &quot;heavy lifting&quot; on the continuous signal:</p><ul><li><p><strong>Rereferencing</strong>: Standardizing the electrode voltages.</p></li><li><p><strong>Filtering</strong>: Removing slow drifts (High-pass) and high-frequency noise (Low-pass).</p></li><li><p><strong>Artifact Detection</strong>: Finding segments with extreme amplitudes or bad channel profiles.</p></li><li><p><strong>ICA Component Removal</strong>: Automatically identifying and removing eye blinks, muscle noise, and line interference.</p></li><li><p><strong>Electrode Interpolation</strong>: Repairing &quot;bad&quot; scalp channels using their spatial neighbors.</p></li></ul><h3 id="Phase-3:-Epoching-and-Cleanup" tabindex="-1">Phase 3: Epoching &amp; Cleanup <a class="header-anchor" href="#Phase-3:-Epoching-and-Cleanup" aria-label="Permalink to &quot;Phase 3: Epoching &amp;amp; Cleanup {#Phase-3:-Epoching-and-Cleanup}&quot;">​</a></h3><p>Once the continuous data is cleaned, the pipeline focuses on the specific experimental windows:</p><ul><li><p><strong>Epoch Extraction</strong>: Cutting the data into segments based on triggers.</p></li><li><p><strong>Baseline Correction</strong>: Ensuring each segment starts from a zero-volt average.</p></li><li><p><strong>Per-Epoch Repair</strong>: Interpolating electrodes that only became &quot;bad&quot; during specific segments of the task.</p></li><li><p><strong>Epoch Rejection</strong>: Final removal of any segments that remain too noisy to analyze.</p></li></ul><h3 id="Phase-4:-Cohort-Consolidation" tabindex="-1">Phase 4: Cohort Consolidation <a class="header-anchor" href="#Phase-4:-Cohort-Consolidation" aria-label="Permalink to &quot;Phase 4: Cohort Consolidation {#Phase-4:-Cohort-Consolidation}&quot;">​</a></h3><p>After the last participant is processed, the pipeline automatically generates summaries of the entire study:</p><ul><li><p><strong>Grand Average Counts</strong>: A report on how many trials survived for each participant/condition.</p></li><li><p><strong>Electrode Reliability</strong>: A summary identifying which electrodes were frequently repaired across the cohort.</p></li><li><p><strong>ICA Statistics</strong>: Reports on the average number and type of components removed per subject.</p></li></ul><h2 id="3.-Resilience-and-Isolation" tabindex="-1">3. Resilience and Isolation <a class="header-anchor" href="#3.-Resilience-and-Isolation" aria-label="Permalink to &quot;3. Resilience and Isolation {#3.-Resilience-and-Isolation}&quot;">​</a></h2><p>The pipeline is built to be &quot;fail-safe.&quot;</p><ol><li><p><strong>Logical Isolation</strong>: If a specific participant&#39;s file is corrupted or missing, the pipeline logs the error but continues processing the rest of the cohort.</p></li><li><p><strong>Log Granularity</strong>: You receive a <strong>Study-level log</strong> summarizing the entire run, plus <strong>Individual-level logs</strong> for every participant, containing every table and warning generated during their specific processing.</p></li><li><p><strong>Traceability</strong>: Each output file is marked with metadata about the pipeline version and parameters used to create it.</p></li></ol><hr><div class="tip custom-block github-alert"><p class="custom-block-title">You can find the reference implementation for this entire flow in \`src/pipelines/pipeline_v1.jl\`.</p><p></p></div>`,24)])])}const d=i(s,[["render",o]]);export{g as __pageData,d as default};
